    loadTime: 9, loadKind: 'pressure'
  },
  {
    id: 'hay', name: 'HAY DELIVERY', pay: 110,
    pickup: 'barn', drop: 'store', cargo: 'HAY',
    desc: 'Twelve bales for the feed store. Keep it under thirty or the load walks off the trailer.',
    loadTime: 5, loadKind: 'hold'
  },
  {
    id: 'scrap', name: 'SCRAP HAUL', pay: 160,
    pickup: 'scrapyard', drop: 'sawmill', cargo: 'SCRAP',
    desc: 'A load of bent steel for the mill. Heavy. The tractor will feel every pothole.',
    loadTime: 7, loadKind: 'hold'
  }
];

export const JOB_MAP = Object.fromEntries(JOBS.map(j => [j.id, j]));

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (a, b) => a + Math.random() * (b - a);
export const pick = arr => arr[Math.floor(Math.random() * arr.length)];

import { PARTS, PART_MAP, TUNE, SURVIVAL_DECAY, JOB_MAP, clamp } from './data.js';

const SAVE_KEY = 'hardstart.save.v1';

function freshParts() {
  const o = {};
  for (const p of PARTS) o[p.id] = { installed: false, torque: 0, loose: false, stripped: false, perfect: false };
  return o;
}

export function createState() {
  return {
    version: 1,
    started: false,
    mode: 'title',
    cash: 40,
    day: 1,
    minutes: 6 * 60 + 40,
    health: 100,
    survival: { hunger: 68, thirst: 62, fatigue: 28, stress: 22, hygiene: 58 },
    parts: freshParts(),
    tune: { mixture: TUNE.mixture.start, valve: TUNE.valve.start, timing: TUNE.timing.start, running: false, started: false, quality: 0 },
    tractor: { fuel: 68, damage: 0, atHome: true },
    job: null,
    jobsDone: 0,
    stats: { bolts: 0, stripped: 0, loose: 0, distance: 0, earned: 0, crashes: 0, nearMisses: 0 },
    cause: '',
    lastSaved: 0
  };
}

class GameState {
  constructor() {
    this.s = createState();
    this.onDeath = null;
    this.onChange = null;
    this.onToast = null;
    this._acc = 0;
  }

  reset() {
    this.s = createState();
    this.save();
    this.changed();
  }

  changed() { if (this.onChange) this.onChange(); }
  toast(msg, kind = '') { if (this.onToast) this.onToast(msg, kind); }

  // ---------- time & survival ----------
  clockLabel() {
    const m = Math.floor(this.s.minutes % 1440);
    const h = Math.floor(m / 60), mm = m % 60;
    return `${String(h).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
  }

  advanceMinutes(n) {
    this.s.minutes += n;
    while (this.s.minutes >= 1440) { this.s.minutes -= 1440; this.s.day++; }
    // passive survival drain while time passes
    const sv = this.s.survival;
    sv.hunger = clamp(sv.hunger - SURVIVAL_DECAY.hunger * n, 0, 100);
    sv.thirst = clamp(sv.thirst - SURVIVAL_DECAY.thirst * n, 0, 100);
    sv.fatigue = clamp(sv.fatigue + SURVIVAL_DECAY.fatigue * n, 0, 100);
    sv.stress = clamp(sv.stress + SURVIVAL_DECAY.stress * n * (1 + (100 - sv.hygiene) / 180), 0, 100);
    sv.hygiene = clamp(sv.hygiene - SURVIVAL_DECAY.hygiene * n, 0, 100);
    this.changed();
  }

  tick(dt) {
    if (this.s.mode === 'title' || this.s.mode === 'dead') return;
    const minutesPerSecond = 1.1;
    this._acc += dt * minutesPerSecond;
    if (this._acc >= 1) {
      const whole = Math.floor(this._acc);
      this._acc -= whole;
      this.advanceMinutes(whole);
      this.checkVitals(whole);
    }
  }

  checkVitals(mins) {
    const sv = this.s.survival;
    let dmg = 0, cause = '';
    if (sv.hunger <= 0) { dmg += 0.7 * mins; cause = 'STARVATION'; }
    if (sv.thirst <= 0) { dmg += 1.1 * mins; cause = 'DEHYDRATION'; }
    if (sv.fatigue >= 100) { dmg += 0.45 * mins; cause = cause || 'EXHAUSTION'; }
    if (sv.stress >= 100) { dmg += 0.35 * mins; cause = cause || 'STRESS'; }
    if (sv.hunger > 45 && sv.thirst > 45 && sv.fatigue < 45 && sv.stress < 55 && this.s.health < 100) {
      this.s.health = Math.min(100, this.s.health + 0.05 * mins);
    }
    if (dmg > 0) {
      this.s.health -= dmg;
      if (this.s.health <= 0) { this.die(cause); return; }
    }
    if (this.s.health < 30 && Math.random() < 0.004 * mins) {
      this.toast('YOUR HANDS ARE SHAKING.', 'warn');
    }
  }

  // ---------- home actions ----------
  action(kind) {
    const sv = this.s.survival;
    if (kind === 'eat') {
      if (this.s.cash < 6) return this.toast('NO CASH. CHECK THE COUCH CUSHIONS.', 'bad');
      this.s.cash -= 6;
      sv.hunger = clamp(sv.hunger + 38, 0, 100);
      sv.stress = clamp(sv.stress - 4, 0, 100);
      this.advanceMinutes(25);
      this.toast('COLD BEANS. $6 GONE.', 'good');
    } else if (kind === 'drink') {
      sv.thirst = clamp(sv.thirst + 46, 0, 100);
      this.advanceMinutes(5);
      this.toast('TAP WATER. TASTES LIKE RUST.', 'good');
    } else if (kind === 'wash') {
      if (this.s.cash < 2) return this.toast('NO CASH FOR SOAP.', 'bad');
      this.s.cash -= 2;
      sv.hygiene = clamp(sv.hygiene + 55, 0, 100);
      sv.stress = clamp(sv.stress - 8, 0, 100);
      this.advanceMinutes(20);
      this.toast('COLD SHOWER. YOU SMELL ALMOST HUMAN.', 'good');
    } else if (kind === 'sleep') {
      this.sleep(8 * 60);
    }
    this.save();
    this.changed();
  }

  sleep(mins) {
    const sv = this.s.survival;
    this.advanceMinutes(mins);
    sv.fatigue = clamp(sv.fatigue - mins * 0.14, 0, 100);
    sv.stress = clamp(sv.stress - mins * 0.055, 0, 100);
    this.s.health = clamp(this.s.health + mins * 0.03, 0, 100);
    this.toast(`SLEPT ${Math.round(mins / 60)} HOURS.`, 'good');
    this.save();
    this.changed();
  }

  // ---------- garage ----------
  partState(id) { return this.s.parts[id]; }
  builtCount() { return PARTS.filter(p => this.s.parts[p.id].installed).length; }

  canFit(id) {
    const def = PART_MAP[id];
    if (!def) return false;
    if (this.s.parts[id].installed) return false;
    return def.requires.every(r => this.s.parts[r].installed);
  }

  installPart(id, result) {
    const st = this.s.parts[id];
    const def = PART_MAP[id];
    st.installed = true;
    st.loose = result.loose || false;
    st.perfect = result.perfect || false;
    st.torque = result.torque || 0;
    st.stripped = false;
    this.s.stats.bolts += def.bolts || 1;
    if (st.loose) this.s.stats.loose++;
    this.advanceMinutes(def.bolts ? 12 + def.bolts * 4 : 8);
    this.save();
    this.changed();
  }

  stripPart(id) {
    const st = this.s.parts[id];
    st.installed = false;
    st.stripped = true;
    st.loose = false;
    st.torque = 0;
    this.s.stats.stripped++;
    this.s.survival.stress = clamp(this.s.survival.stress + 14, 0, 100);
    this.advanceMinutes(10);
    this.save();
    this.changed();
  }

  replacePart(id) {
    const def = PART_MAP[id];
    const st = this.s.parts[id];
    if (!st.stripped) return false;
    this.s.cash -= def.price;
    st.stripped = false;
    st.installed = false;
    this.advanceMinutes(30);
    if (this.s.cash < 0) this.toast(`REPLACEMENT ON THE TAB. YOU OWE $${Math.abs(this.s.cash)}.`, 'warn');
    else this.toast(`${def.name} REPLACED. $${def.price}.`, 'good');
    this.save();
    this.changed();
    return true;
  }

  reliability() {
    let r = 100;
    for (const p of PARTS) {
      const st = this.s.parts[p.id];
      if (!st.installed) r -= 6;
      else if (st.loose) r -= 14;
      else if (st.perfect) r += 1.5;
    }
    return clamp(r, 0, 100);
  }

  // ---------- tuning ----------
  tuneQuality() {
    const t = this.s.tune;
    const dm = Math.abs(t.mixture - TUNE.mixture.ideal) / TUNE.mixture.tol;
    const dv = Math.abs(t.valve - TUNE.valve.ideal) / TUNE.valve.tol;
    const dt = Math.abs(t.timing - TUNE.timing.ideal) / TUNE.timing.tol;
    return clamp(100 - (dm + dv + dt) * 17, 0, 100);
  }

  idleRpm() {
    const q = this.s.tune.quality;
    return Math.max(0, Math.round(760 + (100 - q) * 5 + Math.sin(Date.now() / 220) * (100 - q) * 0.9));
  }

  // ---------- economy ----------
  addCash(n) {
    this.s.cash += n;
    if (n > 0) this.s.stats.earned += n;
    this.save();
    this.changed();
  }

  // ---------- damage / death ----------
  damage(amount, cause) {
    this.s.health -= amount;
    if (this.s.health <= 0) this.die(cause);
    else this.changed();
  }

  die(cause) {
    if (this.s.mode === 'dead') return;
    this.s.health = 0;
    this.s.cause = cause;
    this.s.mode = 'dead';
    this.save();
    if (this.onDeath) this.onDeath(cause);
  }

  // ---------- jobs ----------
  acceptJob(id) {
    const def = JOB_MAP[id];
    if (!def) return;
    this.s.job = { id, stage: 'pickup' };
    this.toast(`JOB TAKEN — ${def.name}`, 'good');
    this.save();
    this.changed();
  }

  advanceJob() {
    if (!this.s.job) return;
    const def = JOB_MAP[this.s.job.id];
    if (this.s.job.stage === 'pickup') {
      this.s.job.stage = 'drop';
      this.toast(`${def.cargo} LOADED. DELIVER TO ${def.drop.toUpperCase()}.`, 'good');
    } else {
      this.s.cash += def.pay;
      this.s.stats.earned += def.pay;
      this.s.jobsDone++;
      this.s.job = null;
      this.s.survival.fatigue = clamp(this.s.survival.fatigue + 9, 0, 100);
      this.s.survival.stress = clamp(this.s.survival.stress - 6, 0, 100);
      this.toast(`DELIVERED. +$${def.pay}`, 'good');
      this.save();
    }
    this.changed();
  }

  // ---------- save ----------
  save() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(this.s));
    } catch (e) { /* storage full or blocked */ }
  }

  hasSave() {
    try { return !!localStorage.getItem(SAVE_KEY); } catch (e) { return false; }
  }

  load() {
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return false;
      const data = JSON.parse(raw);
      if (!data || data.version !== 1) return false;
      // merge with a fresh state so missing keys are filled
      const base = createState();
      this.s = Object.assign(base, data);
      this.s.parts = Object.assign(freshParts(), data.parts || {});
      this.s.survival = Object.assign(base.survival, data.survival || {});
      this.s.tune = Object.assign(base.tune, data.tune || {});
      this.s.tractor = Object.assign(base.tractor, data.tractor || {});
      this.s.stats = Object.assign(base.stats, data.stats || {});
      this.s.mode = 'garage';
      this.changed();
      return true;
    } catch (e) { return false; }
  }

  wipe() {
    try { localStorage.removeItem(SAVE_KEY); } catch (e) { /* ignore */ }
  }
}

export const game = new GameState();

// ---------- procedural audio ----------
export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.engine = null;
    this.wind = null;
    this.pump = null;
    this.muted = false;
    this.ready = false;
  }

  init() {
    if (this.ready) { this.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.85;
      this.master.connect(this.ctx.destination);
      this.noiseBuf = this.makeNoise(2);
      this.ready = true;
      this.startWind();
    } catch (e) { console.warn('audio unavailable', e); }
  }

  resume() { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : 0.85, this.ctx.currentTime, 0.05);
    return this.muted;
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      d[i] = last * 3.2;
    }
    return buf;
  }

  // ---------- one-shots ----------
  blip(freq = 440, dur = 0.05, type = 'square', vol = 0.06) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  click() { this.blip(520, 0.03, 'square', 0.035); }
  beep(ok = true) { this.blip(ok ? 760 : 190, 0.1, 'triangle', 0.06); }

  noiseHit(dur = 0.08, freq = 1200, vol = 0.14, q = 1) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass'; f.frequency.value = freq; f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t); src.stop(t + dur + 0.02);
  }

  ratchet() {
    if (!this.ready) return;
    for (let i = 0; i < 4; i++) {
      setTimeout(() => this.noiseHit(0.028, 2400 + Math.random() * 800, 0.13, 2), i * 42);
    }
  }

  slip() {
    if (!this.ready) return;
    this.noiseHit(0.14, 3400, 0.12, 6);
    this.blip(110, 0.1, 'sawtooth', 0.03);
  }

  clunk() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sine'; o.frequency.setValueAtTime(130, t);
    o.frequency.exponentialRampToValueAtTime(48, t + 0.18);
    g.gain.setValueAtTime(0.22, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.26);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + 0.3);
    this.noiseHit(0.05, 700, 0.1, 1);
  }

  thunk() {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'triangle'; o.frequency.setValueAtTime(90, t);
    o.frequency.exponentialRampToValueAtTime(40, t + 0.2);
    g.gain.setValueAtTime(0.18, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + 0.34);
  }

  backfire() {
    if (!this.ready) return;
    this.noiseHit(0.28, 260, 0.34, 0.7);
    this.noiseHit(0.12, 1600, 0.1, 1.5);
    this.blip(70, 0.3, 'sawtooth', 0.09);
  }

  cash() {
    if (!this.ready) return;
    [880, 1180, 1560].forEach((f, i) => setTimeout(() => this.blip(f, 0.09, 'triangle', 0.05), i * 55));
  }

  pumpStart() {
    if (!this.ready || this.pump) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sawtooth'; o.frequency.value = 62;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 220;
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(0.09, t + 0.2);
    o.connect(f).connect(g).connect(this.master);
    o.start();
    this.pump = { o, g, f };
  }

  pumpSet(load = 1) {
    if (!this.pump) return;
    const t = this.ctx.currentTime;
    this.pump.o.frequency.setTargetAtTime(58 + load * 26, t, 0.08);
    this.pump.f.frequency.setTargetAtTime(180 + load * 420, t, 0.08);
  }

  pumpStop() {
    if (!this.pump) return;
    const { o, g } = this.pump;
    const t = this.ctx.currentTime;
    g.gain.setTargetAtTime(0, t, 0.08);
    o.stop(t + 0.4);
    this.pump = null;
  }

  // ---------- engine ----------
  startEngine(rpm = 800) {
    if (!this.ready || this.engine) { this.setEngine(rpm, 0.2); return; }
    const t = this.ctx.currentTime;
    const o1 = this.ctx.createOscillator();
    const o2 = this.ctx.createOscillator();
    const o3 = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    const noise = this.ctx.createBufferSource();
    const nGain = this.ctx.createGain();
    const nFilter = this.ctx.createBiquadFilter();

    o1.type = 'sawtooth'; o1.frequency.value = rpm / 30;
    o2.type = 'square'; o2.frequency.value = rpm / 15;
    o3.type = 'triangle'; o3.frequency.value = rpm / 60;
    filter.type = 'lowpass'; filter.frequency.value = 420; filter.Q.value = 2.2;
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(0.13, t + 0.5);

    noise.buffer = this.noiseBuf; noise.loop = true;
    nFilter.type = 'bandpass'; nFilter.frequency.value = 140; nFilter.Q.value = 0.7;
    nGain.gain.value = 0.035;

    o1.connect(filter); o2.connect(filter); o3.connect(filter);
    filter.connect(gain).connect(this.master);
    noise.connect(nFilter).connect(nGain).connect(this.master);

    o1.start(); o2.start(); o3.start(); noise.start();
    this.engine = { o1, o2, o3, gain, filter, noise, nGain, nFilter };
    this.setEngine(rpm, 0.15);
  }

  setEngine(rpm, load = 0) {
    if (!this.engine || !this.ready) return;
    const t = this.ctx.currentTime;
    const f = Math.max(18, rpm / 30);
    const e = this.engine;
    e.o1.frequency.setTargetAtTime(f, t, 0.06);
    e.o2.frequency.setTargetAtTime(f * 2.01, t, 0.06);
    e.o3.frequency.setTargetAtTime(f * 0.5, t, 0.08);
    e.filter.frequency.setTargetAtTime(260 + load * 900 + rpm * 0.12, t, 0.08);
    e.nGain.gain.setTargetAtTime(0.025 + load * 0.05, t, 0.1);
    e.gain.gain.setTargetAtTime(0.11 + load * 0.06, t, 0.12);
  }

  stopEngine() {
    if (!this.engine || !this.ready) return;
    const e = this.engine;
    const t = this.ctx.currentTime;
    e.gain.gain.setTargetAtTime(0, t, 0.12);
    e.nGain.gain.setTargetAtTime(0, t, 0.12);
    setTimeout(() => {
      try { e.o1.stop(); e.o2.stop(); e.o3.stop(); e.noise.stop(); } catch (err) { /* already stopped */ }
    }, 500);
    this.engine = null;
  }

  // ---------- ambience ----------
  startWind() {
    if (!this.ready || this.wind) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf; src.loop = true;
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass'; f.frequency.value = 420; f.Q.value = 0.45;
    const g = this.ctx.createGain();
    g.gain.value = 0.022;
    const lfo = this.ctx.createOscillator();
    const lfoGain = this.ctx.createGain();
    lfo.frequency.value = 0.08; lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain).connect(g.gain);
    src.connect(f).connect(g).connect(this.master);
    src.start(); lfo.start();
    this.wind = { src, g, f };
  }

  setWind(level) {
    if (!this.wind) return;
    this.wind.g.gain.setTargetAtTime(0.012 + level * 0.03, this.ctx.currentTime, 0.4);
  }
}

