import * as THREE from 'three';

function canvas(size = 512) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}

function finish(c, repeat = 1) {
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat, repeat);
  t.anisotropy = 8;
  return t;
}

export function concreteTexture(size = 512) {
  const c = canvas(size), x = c.getContext('2d');
  x.fillStyle = '#5d594f'; x.fillRect(0, 0, size, size);
  // mottling
  for (let i = 0; i < 2600; i++) {
    const r = Math.random() * 2.4;
    const g = 70 + Math.random() * 55;
    x.fillStyle = `rgba(${g},${g - 4},${g - 10},${Math.random() * 0.16})`;
    x.beginPath(); x.arc(Math.random() * size, Math.random() * size, r, 0, 7); x.fill();
  }
  // dark stains
  for (let i = 0; i < 16; i++) {
    const cx = Math.random() * size, cy = Math.random() * size, r = 20 + Math.random() * 90;
    const grd = x.createRadialGradient(cx, cy, 0, cx, cy, r);
    grd.addColorStop(0, `rgba(22,20,16,${0.12 + Math.random() * 0.18})`);
    grd.addColorStop(1, 'rgba(22,20,16,0)');
    x.fillStyle = grd; x.beginPath(); x.arc(cx, cy, r, 0, 7); x.fill();
  }
  // cracks
  x.strokeStyle = 'rgba(30,28,24,.35)'; x.lineWidth = 1;
  for (let i = 0; i < 7; i++) {
    let px = Math.random() * size, py = Math.random() * size;
    x.beginPath(); x.moveTo(px, py);
    for (let j = 0; j < 9; j++) { px += (Math.random() - 0.5) * 46; py += (Math.random() - 0.5) * 46; x.lineTo(px, py); }
    x.stroke();
  }
  return finish(c);
}

export function dirtTexture(size = 512) {
  const c = canvas(size), x = c.getContext('2d');
  x.fillStyle = '#6b5c42'; x.fillRect(0, 0, size, size);
  for (let i = 0; i < 4200; i++) {
    const g = 50 + Math.random() * 70;
    x.fillStyle = `rgba(${g + 20},${g + 6},${g - 14},${Math.random() * 0.2})`;
    x.fillRect(Math.random() * size, Math.random() * size, 1 + Math.random() * 3, 1 + Math.random() * 3);
  }
  for (let i = 0; i < 26; i++) {
    const cx = Math.random() * size, cy = Math.random() * size, r = 14 + Math.random() * 55;
    const grd = x.createRadialGradient(cx, cy, 0, cx, cy, r);
    grd.addColorStop(0, 'rgba(38,32,22,.22)');
    grd.addColorStop(1, 'rgba(38,32,22,0)');
    x.fillStyle = grd; x.beginPath(); x.arc(cx, cy, r, 0, 7); x.fill();
  }
  return finish(c);
}

export function grassTexture(size = 512) {
  const c = canvas(size), x = c.getContext('2d');
  x.fillStyle = '#5b6440'; x.fillRect(0, 0, size, size);
  for (let i = 0; i < 9000; i++) {
    const g = 60 + Math.random() * 70;
    x.strokeStyle = `rgba(${g - 8},${g + 12},${g - 26},${0.12 + Math.random() * 0.25})`;
    x.lineWidth = 1;
    const px = Math.random() * size, py = Math.random() * size;
    x.beginPath(); x.moveTo(px, py); x.lineTo(px + (Math.random() - 0.5) * 3, py - 2 - Math.random() * 4); x.stroke();
  }
  for (let i = 0; i < 20; i++) {
    const cx = Math.random() * size, cy = Math.random() * size, r = 20 + Math.random() * 80;
    const grd = x.createRadialGradient(cx, cy, 0, cx, cy, r);
    grd.addColorStop(0, 'rgba(70,72,38,.16)');
    grd.addColorStop(1, 'rgba(70,72,38,0)');
    x.fillStyle = grd; x.beginPath(); x.arc(cx, cy, r, 0, 7); x.fill();
  }
  return finish(c);
}

export function roadTexture(size = 256) {
  const c = canvas(size), x = c.getContext('2d');
  x.fillStyle = '#4c4438'; x.fillRect(0, 0, size, size);
  for (let i = 0; i < 2600; i++) {
    const g = 45 + Math.random() * 65;
    x.fillStyle = `rgba(${g + 14},${g + 8},${g - 4},${Math.random() * 0.3})`;
    x.fillRect(Math.random() * size, Math.random() * size, 1 + Math.random() * 2.4, 1 + Math.random() * 2.4);
  }
  // wheel ruts
  x.fillStyle = 'rgba(28,24,18,.18)';
  x.fillRect(size * 0.2, 0, size * 0.11, size);
  x.fillRect(size * 0.68, 0, size * 0.11, size);
  return finish(c);
}

export function woodTexture(size = 512) {
  const c = canvas(size), x = c.getContext('2d');
  x.fillStyle = '#5a432c'; x.fillRect(0, 0, size, size);
  for (let i = 0; i < 220; i++) {
    const y = Math.random() * size;
    x.strokeStyle = `rgba(${20 + Math.random() * 40},${14 + Math.random() * 28},${8 + Math.random() * 18},${Math.random() * 0.28})`;
    x.lineWidth = 0.6 + Math.random() * 1.8;
    x.beginPath(); x.moveTo(0, y);
    for (let px = 0; px <= size; px += 16) x.lineTo(px, y + Math.sin(px * 0.02 + i) * 2.4 + (Math.random() - 0.5) * 2);
    x.stroke();
  }
  for (let i = 0; i < 10; i++) {
    const cx = Math.random() * size, cy = Math.random() * size;
    x.strokeStyle = 'rgba(25,16,8,.4)'; x.lineWidth = 1.4;
    x.beginPath(); x.ellipse(cx, cy, 8 + Math.random() * 16, 3 + Math.random() * 6, Math.random(), 0, 7); x.stroke();
  }
  return finish(c);
}

export function pegboardTexture(size = 512) {
  const c = canvas(size), x = c.getContext('2d');
  x.fillStyle = '#7c6a4c'; x.fillRect(0, 0, size, size);
  for (let i = 0; i < 3000; i++) {
    x.fillStyle = `rgba(30,24,16,${Math.random() * 0.12})`;
    x.fillRect(Math.random() * size, Math.random() * size, 2, 2);
  }
  x.fillStyle = 'rgba(24,20,14,.55)';
  const step = 32;
  for (let y = step / 2; y < size; y += step) for (let xx = step / 2; xx < size; xx += step) {
    x.beginPath(); x.arc(xx, y, 2.6, 0, 7); x.fill();
  }
  return finish(c);
}

export function signTexture(text, sub = '', bg = '#1a1712', fg = '#e9e2d2', accent = '#d2601f') {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 256;
  const x = c.getContext('2d');
  x.fillStyle = bg; x.fillRect(0, 0, 512, 256);
  x.strokeStyle = accent; x.lineWidth = 6; x.strokeRect(14, 14, 484, 228);
  x.fillStyle = fg;
  x.font = 'bold 88px "Arial Narrow", sans-serif';
  x.textAlign = 'center'; x.textBaseline = 'middle';
  x.fillText(text, 256, sub ? 112 : 132);
  if (sub) {
    x.fillStyle = accent;
    x.font = '500 26px monospace';
    x.fillText(sub, 256, 190);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function labelTexture(text, fg = '#e9e2d2', bg = '#17140f') {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 64;
  const x = c.getContext('2d');
  x.fillStyle = bg; x.fillRect(0, 0, 256, 64);
  x.fillStyle = fg; x.font = 'bold 30px monospace'; x.textAlign = 'center'; x.textBaseline = 'middle';
  x.fillText(text, 128, 34);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

import * as THREE from 'three';
import { PARTS, PART_MAP, clamp, lerp } from './data.js';
import { game } from './state.js';
import { concreteTexture, woodTexture, pegboardTexture, signTexture, labelTexture } from './textures.js';

const SLOT_INFO = {
  crank:     { anchor: [0, 1.02, -1.05], pick: [0.9, 0.5, 1.2], camR: 2.7, theta: Math.PI },
  pistons:   { anchor: [0, 1.46, -1.05], pick: [0.8, 0.3, 1.1], camR: 2.5, theta: Math.PI },
  oilpan:    { anchor: [0, 0.72, -1.05], pick: [0.9, 0.35, 1.1], camR: 2.7, theta: Math.PI },
  gasket:    { anchor: [0, 1.42, -1.05], pick: [0.95, 0.12, 1.2], camR: 2.6, theta: Math.PI },
  head:      { anchor: [0, 1.58, -1.05], pick: [1.0, 0.4, 1.2], camR: 2.8, theta: Math.PI },
  carb:      { anchor: [0, 1.9, -1.05], pick: [0.5, 0.5, 0.5], camR: 2.4, theta: Math.PI },
  wiring:    { anchor: [0.45, 1.25, -1.4], pick: [1.3, 0.8, 0.9], camR: 2.9, theta: 2.4 },
  battery:   { anchor: [-0.62, 1.0, -1.5], pick: [0.55, 0.45, 0.5], camR: 2.4, theta: 2.8 },
  radiator:  { anchor: [0, 1.15, -1.85], pick: [1.1, 0.75, 0.3], camR: 2.8, theta: Math.PI },
  fueltank:  { anchor: [0, 0.95, 1.55], pick: [1.2, 0.5, 0.7], camR: 2.8, theta: 0.2 },
  driveshaft:{ anchor: [0, 0.52, 0.5], pick: [0.4, 0.4, 2.0], camR: 2.8, theta: 0.8 },
  wheels:    { anchor: [0.88, 0.46, 1.35], pick: [0.4, 0.95, 1.0], camR: 3.0, theta: Math.PI / 2 },
  seat:      { anchor: [0, 1.08, 0.55], pick: [0.7, 0.8, 0.8], camR: 2.5, theta: 0.6 },
  steering:  { anchor: [0, 1.32, -0.1], pick: [0.6, 0.6, 0.6], camR: 2.4, theta: 0.9 }
};

export class Garage {
  constructor(renderer, sound, cb = {}) {
    this.renderer = renderer;
    this.sound = sound;
    this.cb = cb;
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x0a0907);
    this.scene.fog = new THREE.FogExp2(0x0a0907, 0.017);
    this.camera = new THREE.PerspectiveCamera(47, 1, 0.1, 120);

    this.car = new THREE.Group();
    this.scene.add(this.car);
    this.partMeshes = {};
    this.markers = {};
    this.picks = [];
    this.anim = [];
    this.smoke = [];
    this.time = 0;
    this.hoverId = null;
    this.selectedId = null;
    this.inputEnabled = true;
    this.running = false;

    this.orbit = { theta: 2.32, phi: 1.12, radius: 8.4 };
    this.cam = { target: new THREE.Vector3(0, 1.05, 0), radius: 8.4, theta: 2.32, phi: 1.12 };
    this.desired = { target: new THREE.Vector3(0, 1.05, 0), radius: 8.4, theta: 2.32, phi: 1.12 };

    this.pointer = new THREE.Vector2(-2, -2);
    this.raycaster = new THREE.Raycaster();
    this.down = null;
    this.dragging = false;

    this.makeMaterials();
    this.makeEnvironment();
    this.buildRoom();
    this.buildCar();
    this.bindInput();
    this.resize();
  }

  // ---------------------------------------------------------------- materials
  makeMaterials() {
    const std = (o) => new THREE.MeshStandardMaterial(o);
    this.M = {
      steel: std({ color: 0x9b9a94, metalness: 0.9, roughness: 0.38 }),
      dark: std({ color: 0x2c2c29, metalness: 0.72, roughness: 0.58 }),
      cast: std({ color: 0x4a4943, metalness: 0.55, roughness: 0.8 }),
      block: std({ color: 0x55544c, metalness: 0.5, roughness: 0.78 }),
      rust: std({ color: 0x7d4526, metalness: 0.4, roughness: 0.94 }),
      orange: std({ color: 0xb5541e, metalness: 0.35, roughness: 0.58 }),
      yellow: std({ color: 0xc99a34, metalness: 0.4, roughness: 0.6 }),
      chrome: std({ color: 0xd9d8d1, metalness: 1, roughness: 0.14 }),
      rubber: std({ color: 0x141413, metalness: 0, roughness: 0.96 }),
      vinyl: std({ color: 0x2e2319, metalness: 0.05, roughness: 0.88 }),
      copper: std({ color: 0xa9662f, metalness: 0.85, roughness: 0.4 }),
      brass: std({ color: 0xb08a3e, metalness: 0.9, roughness: 0.35 }),
      black: std({ color: 0x121211, metalness: 0.3, roughness: 0.8 }),
      red: std({ color: 0x8b2c1c, metalness: 0.35, roughness: 0.62 }),
      blue: std({ color: 0x2f4a5c, metalness: 0.35, roughness: 0.62 }),
      wood: std({ map: woodTexture(), color: 0xffffff, roughness: 0.9 }),
      concrete: std({ map: concreteTexture(), color: 0xb9b4a8, roughness: 0.95 }),
      peg: std({ map: pegboardTexture(), color: 0xcbb894, roughness: 0.9 }),
      glass: new THREE.MeshStandardMaterial({ color: 0x9fb4b8, metalness: 0.4, roughness: 0.1, transparent: true, opacity: 0.3 }),
      glow: new THREE.MeshBasicMaterial({ color: 0xffd9a0 }),
      white: std({ color: 0xd9d4c4, roughness: 0.7 }),
      green: std({ color: 0x4a5d38, metalness: 0.2, roughness: 0.8 })
    };
    this.M.concrete.map.repeat.set(5, 4);
    this.M.concrete.map.wrapS = this.M.concrete.map.wrapT = THREE.RepeatWrapping;
    this.M.wood.map.repeat.set(3, 1);
    this.M.peg.map.repeat.set(2.4, 1.2);
  }

  makeEnvironment() {
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    const env = new THREE.Scene();
    env.background = new THREE.Color(0x181410);
    const add = (color, w, h, pos, rot) => {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color }));
      m.position.set(...pos); m.rotation.set(...rot); env.add(m);
    };
    add(0xffd9a4, 7, 5, [0, 6, 0], [Math.PI / 2, 0, 0]);
    add(0x7a8fa8, 4, 6, [-8, 3, 0], [0, Math.PI / 2, 0]);
    add(0xff8c3a, 3, 2, [6, 2.5, -4], [0, -Math.PI / 2, 0]);
    add(0x2a241c, 10, 10, [0, -2, 0], [-Math.PI / 2, 0, 0]);
    const tex = pmrem.fromScene(env, 0.06).texture;
    this.scene.environment = tex;
    pmrem.dispose();
  }

  // ---------------------------------------------------------------- helpers
  add(mesh, parent = this.scene) {
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
  }

  box(w, h, d, m, x, y, z, parent = this.scene) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
    mesh.position.set(x, y, z);
    return this.add(mesh, parent);
  }

  cyl(rt, rb, h, seg, m, x, y, z, parent = this.scene) {
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), m);
    mesh.position.set(x, y, z);
    return this.add(mesh, parent);
  }

  // ---------------------------------------------------------------- room
  buildRoom() {
    const M = this.M;
    // floor
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(22, 17), M.concrete);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.scene.add(floor);

    // back wall
    this.box(22, 6, 0.25, M.concrete, 0, 3, -8.5);
    // side walls
    this.box(0.25, 6, 17, M.concrete, -11, 3, 0);
    this.box(0.25, 6, 17, M.concrete, 11, 3, 0);
    // front wall / door
    this.box(22, 6, 0.25, M.concrete, 0, 3, 8.5);
    // ceiling
    this.box(22, 0.2, 17, M.dark, 0, 5.9, 0);

    // roll-up door
    const door = new THREE.Group();
    for (let i = 0; i < 16; i++) {
      const p = this.box(8.4, 0.28, 0.08, i % 2 ? M.steel : M.dark, 0, 0.35 + i * 0.3, 8.3, door);
      p.castShadow = false;
    }
    this.box(0.16, 5.3, 0.16, M.dark, -4.3, 2.65, 8.25, door);
    this.box(0.16, 5.3, 0.16, M.dark, 4.3, 2.65, 8.25, door);
    this.scene.add(door);

    // window
    const win = new THREE.Group();
    const pane = new THREE.Mesh(new THREE.PlaneGeometry(4.2, 2.3), new THREE.MeshBasicMaterial({ color: 0xffcf92 }));
    pane.position.set(5.6, 3.35, -8.34);
    win.add(pane);
    const frameM = M.dark;
    this.box(4.5, 0.12, 0.16, frameM, 5.6, 4.56, -8.3, win);
    this.box(4.5, 0.12, 0.16, frameM, 5.6, 2.14, -8.3, win);
    this.box(0.12, 2.55, 0.16, frameM, 3.38, 3.35, -8.3, win);
    this.box(0.12, 2.55, 0.16, frameM, 7.82, 3.35, -8.3, win);
    this.box(0.08, 2.3, 0.1, frameM, 5.6, 3.35, -8.29, win);
    this.box(4.2, 0.08, 0.1, frameM, 5.6, 3.35, -8.29, win);
    this.scene.add(win);

    // light shafts through window
    const shaftMat = new THREE.MeshBasicMaterial({ color: 0xffcf92, transparent: true, opacity: 0.035, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    for (let i = 0; i < 3; i++) {
      const shaft = new THREE.Mesh(new THREE.PlaneGeometry(1.3, 7.2), shaftMat);
      shaft.position.set(4.6 + i * 1.1, 2.4, -5.4);
      shaft.rotation.set(-0.55, 0, 0.06 * i);
      this.scene.add(shaft);
    }

    // ceiling trusses
    for (let z = -6; z <= 6; z += 3) {
      this.box(21.5, 0.12, 0.14, M.dark, 0, 5.72, z);
      for (let x = -9; x <= 9; x += 3) {
        const t = this.box(0.1, 0.1, 0.1, M.dark, x, 5.72, z);
        t.castShadow = false;
      }
    }
    for (let x = -8; x <= 8; x += 4) this.box(0.14, 0.12, 16.5, M.dark, x, 5.74, 0);

    // lamps
    const lampXs = [-4.4, 0, 4.4];
    for (const lx of lampXs) {
      const shade = new THREE.Mesh(new THREE.ConeGeometry(0.46, 0.36, 18, 1, true), M.dark);
      shade.position.set(lx, 4.72, 0.4);
      shade.rotation.x = Math.PI;
      this.scene.add(shade);
      const bulb = this.cyl(0.1, 0.1, 0.16, 10, M.glow, lx, 4.5, 0.4);
      bulb.castShadow = false;
      const light = new THREE.PointLight(0xffc784, 26, 13, 2);
      light.position.set(lx, 4.35, 0.4);
      this.scene.add(light);
      const cord = this.box(0.03, 0.9, 0.03, M.black, lx, 5.25, 0.4);
      cord.castShadow = false;
    }

    // main spot over the car
    const spot = new THREE.SpotLight(0xfff0d2, 240, 16, 0.78, 0.9, 1.6);
    spot.position.set(0, 5.5, 1.2);
    spot.target.position.set(0, 0.8, -0.4);
    spot.castShadow = true;
    spot.shadow.mapSize.set(1024, 1024);
    spot.shadow.bias = -0.0004;
    this.scene.add(spot, spot.target);

    // daylight through window
    const sun = new THREE.DirectionalLight(0xffd7a2, 2.4);
    sun.position.set(8, 6, -9);
    sun.target.position.set(0, 0.8, 0);
    sun.castShadow = true;
    sun.shadow.mapSize.set(1024, 1024);
    sun.shadow.camera.left = -8; sun.shadow.camera.right = 8;
    sun.shadow.camera.top = 8; sun.shadow.camera.bottom = -8;
    sun.shadow.bias = -0.0006;
    this.scene.add(sun, sun.target);

    const hemi = new THREE.HemisphereLight(0x8d9bab, 0x2a2118, 0.55);
    this.scene.add(hemi);
    const amb = new THREE.AmbientLight(0x6b6254, 0.28);
    this.scene.add(amb);

    // workbench (left)
    const bench = new THREE.Group();
    this.box(5.4, 0.16, 1.5, M.wood, 0, 1.0, 0, bench);
    this.box(5.2, 0.1, 1.3, M.dark, 0, 0.9, 0, bench);
    for (const x of [-2.45, 2.45]) for (const z of [-0.6, 0.6]) this.box(0.14, 0.92, 0.14, M.steel, x, 0.46, z, bench);
    // vise
    this.box(0.5, 0.28, 0.34, M.steel, -2.1, 1.18, 0.2, bench);
    this.box(0.26, 0.14, 0.2, M.dark, -2.1, 1.38, 0.2, bench);
    this.cyl(0.04, 0.04, 0.5, 8, M.steel, -1.85, 1.25, 0.2, bench).rotation.z = Math.PI / 2;
    // scattered tools
    for (let i = 0; i < 7; i++) {
      const t = this.box(0.05 + Math.random() * 0.5, 0.04, 0.05, i % 2 ? M.steel : M.rust, -1.4 + i * 0.55, 1.1, -0.35 + Math.random() * 0.5, bench);
      t.rotation.y = Math.random() * Math.PI;
