      this.cyl(0.055, 0.055, 0.1, 8, M.chrome, 0.16, 0.17, -0.42 + i * 0.28, g).rotation.x = Math.PI / 2;
    }
    const pulley = this.cyl(0.19, 0.19, 0.08, 16, M.dark, 0, 0, -0.6, g);
