  makeFuelTank() {
    const M = this.M, g = new THREE.Group();
    this.box(1.02, 0.38, 0.48, M.rust, 0, 0, 0, g);
    this.box(0.96, 0.06, 0.42, M.dark, 0, 0.22, 0, g);
    for (const x of [-0.34, 0.34]) {
