        void main(){
          vec3 d = normalize(vWorld);
          float h = clamp(d.y*0.5+0.5, 0.0, 1.0);
          vec3 col = mix(bottom, top, pow(h, 0.72));
          float s = max(dot(d, normalize(sunDir)), 0.0);
          col += sunColor * pow(s, 420.0) * 2.4 * sunI;
