  buildStars() {
    const n = 700;
    const pos = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const v = new THREE.Vector3(rand(-1, 1), rand(0.08, 1), rand(-1, 1)).normalize().multiplyScalar(430);
