    if (job) out.push({ x: job.loc.x, z: job.loc.z, label: job.stage === 'pickup' ? 'PICKUP' : 'DROP', color: '#e5b44a' });
    out.push({ x: LOCATIONS.home.x, z: LOCATIONS.home.z, label: 'HOME', color: '#8db268' });
