  .tq-left h2{font-size:22px;margin-top:2px}
  .tq-spec{margin-top:6px}
  .wrench-row{margin-top:8px;gap:5px}
  .wrench{width:42px;height:46px}
  .wrench svg{width:20px;height:20px}
  .tq-log{margin-top:8px;min-height:26px;font-size:8px}
  .tq-right{grid-column:1/-1}
  .tq-right .hold-pad{min-height:64px}
}

